def get_parameters(
    vault: SmartContractVault, param_fetcher_id: str = FOREIGN_TRANSACTION_FEE_POF_ID
) -> dict[str, datetime | Decimal | str | None]:
    """Get foreign transaction fee parameters from vault fetcher.

    Args:
        vault (SmartContractVault): Vault object
        param_fetcher_id (str, optional): Foreign transaction fee fetcher id. Defaults to
            FOREIGN_TRANSACTION_FEE_POF_ID.

    Returns:
        dict[str, datetime | Decimal | str | None]: _description_
    """
    return vault.get_parameters_observation(fetcher_id=param_fetcher_id).parameters


def charge_foreign_transaction_fee(
    state: state_utils.SmartContractState,
    transaction_amount: Decimal,
    account_type: str = "",
    fetchers_config: ForeignTransactionFeeFetchersConfig = DEFAULT_FOREIGN_TRANSACTION_FEE_FETCHERS_CONFIG,  # noqa: E501
) -> list[CustomInstruction]:
    """Charges a foreign transaction fee on international transactions (post_posting_hook).

    Detected via instruction_details["is_foreign_transaction"] == "true".
    For the Apex Reserve Card, this is 0% (no FX fee).

    Args:
        state: The current state of the smart contract.
        transaction_amount: The transaction amount.
        account_type: The account type for GL impact details.
        fetchers_config: Configuration for the fetchers.

    Returns:
        List of custom instructions for the fee (empty if 0%).
    """
    state = state_utils.append_to_state(
        state=state,
        parameters=get_parameters(state.vault, fetchers_config.param_fetcher_id),
    )

    rejection = state_utils.check_parameters_exist(
        state=state,
        param_ids={
            fetchers_config.denomination_param_id,
            FOREIGN_TRANSACTION_FEE_PERCENTAGE_PARAM.id,
            FOREIGN_TRANSACTION_FEE_INCOME_ACCOUNT_PARAM.id,
        },
    )
    assert rejection is None, rejection

    denomination: str = str(state.parameters[fetchers_config.denomination_param_id])
    percentage: Decimal = state.parameters[FOREIGN_TRANSACTION_FEE_PERCENTAGE_PARAM.id]  # type: ignore
    income_account: str = state.parameters[FOREIGN_TRANSACTION_FEE_INCOME_ACCOUNT_PARAM.id]  # type: ignore

    if percentage <= 0:
        return []

    fee = (transaction_amount * percentage).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    if fee <= 0:
        return []

    return [
        CustomInstruction(
            postings=posting_utils.create_postings(
                amount=fee,
                debit_account=state.vault.account_id,
                debit_address=apex_addresses.FEES,
                credit_account=income_account,
                denomination=denomination,
            ),
            value_datetime=state.effective_datetime,
            instruction_details=posting_utils.standard_instruction_details(
                description=f"Foreign transaction fee: {fee} ({percentage * 100}% of "
                f"{transaction_amount})",
                event_type=FOREIGN_TRANSACTION_FEE_EVENT,
                gl_impacted=True,
                account_type=account_type,
            ),
            override_all_restrictions=True,
        )
    ]
